use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    entries: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            entries: HashMap::new(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        self.entries.insert(entry.0, entry.1)
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
}

