use std::io::{self, Write};
use std::process;

const LOGIC_ERROR_MESSAGE: &str =
    "terminate called after throwing an instance of 'std::logic_error'\n  what():  basic_string::_S_construct null not valid\n";
const INVALID_ARGUMENT_MESSAGE: &str =
    "terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi\n";
const OUT_OF_RANGE_MESSAGE: &str =
    "terminate called after throwing an instance of 'std::out_of_range'\n  what():  stoi\n";

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StoiError {
    InvalidArgument,
    OutOfRange,
}

pub fn parse_count(args: &[String]) -> i32 {
    let mut count = 1;

    if args.len() > 1 && args[1] == "--a" {
        let value = match args.get(2) {
            Some(value) => value,
            None => abort_with(LOGIC_ERROR_MESSAGE),
        };

        count = match parse_stoi_i32(value) {
            Ok(parsed) => parsed,
            Err(StoiError::InvalidArgument) => abort_with(INVALID_ARGUMENT_MESSAGE),
            Err(StoiError::OutOfRange) => abort_with(OUT_OF_RANGE_MESSAGE),
        };
    }

    count
}

fn parse_stoi_i32(input: &str) -> Result<i32, StoiError> {
    let bytes = input.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_cxx_space(bytes[index]) {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digits_start = index;
    let limit = if negative {
        i32::MAX as u64 + 1
    } else {
        i32::MAX as u64
    };
    let mut value = 0_u64;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        value = match value
            .checked_mul(10)
            .and_then(|current| current.checked_add((byte - b'0') as u64))
        {
            Some(next) => next,
            None => return Err(StoiError::OutOfRange),
        };

        if value > limit {
            return Err(StoiError::OutOfRange);
        }

        index += 1;
    }

    if index == digits_start {
        return Err(StoiError::InvalidArgument);
    }

    if negative {
        if value == i32::MAX as u64 + 1 {
            Ok(i32::MIN)
        } else {
            Ok(-(value as i32))
        }
    } else {
        Ok(value as i32)
    }
}

fn is_cxx_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\n' | b'\r' | b'\t' | 0x0B | 0x0C)
}

fn abort_with(message: &str) -> ! {
    let mut stderr = io::stderr().lock();
    let _ = stderr.write_all(message.as_bytes());
    let _ = stderr.flush();
    process::abort();
}

